// features/lifecycle.feature: After a replacement, only the new document waits for review
import { expect, expectStatus, test } from "../../fixtures";

test("after a replacement, only the new document waits for review", { tag: "@LIF-05" }, async ({ factory, apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();
  // Approve first: a rejection moves the vendor out of review, after which nothing else can be decided.
  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, { data: { decision: "approve" } }),
    200,
  );
  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, { data: { decision: "approve" } }),
    200,
  );
  await expectStatus(
    await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "reject", note: "Please upload a signed W-9" },
    }),
    200,
  );

  // Act
  const replacement = await factory.upload(vendor.id, "w9");
  await expect
    .poll(
      async () => (await expectStatus<{ status: string }>(await member.get(`/api/documents/${replacement.id}`), 200)).status,
      { message: "the replacement w9 is extracted", timeout: 30_000 },
    )
    .toBe("extracted");
  const submitted = await expectStatus<{ status: string }>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

  // Assert
  expect(submitted.status).toBe("in_review");
  const stored = await expectStatus<{ status: string }>(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("in_review");

  const queue = await expectStatus<
    { vendor_id: string; extractions: { document_id: string; kind: string; status: string }[] }[]
  >(await reviewer.get("/api/review-queue"), 200);
  const entries = queue.filter((item) => item.vendor_id === vendor.id);
  expect(entries, "the vendor appears once in the review queue").toHaveLength(1);
  const pending = entries[0].extractions.filter((e) => e.status === "pending_review");
  expect(pending, "exactly one pending extraction").toHaveLength(1);
  expect(pending[0].kind).toBe("w9");
  expect(pending[0].document_id).toBe(replacement.id);
});
